    assert_eq!(input, before);
    assert_eq!(
        select_regions(&mut input, 0..4, 4..3),
        Err(RangeError::SecondInvalid)
    );
    assert_eq!(input, before);
    assert_eq!(
        select_regions(&mut input, 0..3, 2..4),
        Err(RangeError::Overlap)
